  async function captureLive(){if(controller().busy)return;try{const canvas=root.DV_SCAN_V16_CAMERA.capture($('dvV16Video'),{single:!slabMode()&&(mode==='single'||mode==='continuous'),detectedRect:latestContour&&Date.now()-latestContour.at<500?latestContour.rect:null});stopLive();showSource(canvas);await analyzeSource(canvas,{sourcePrepared:!!canvas.__v16Prepared})}catch(error){controller().transition('error',{error})}}
  function openPicker(kind){if(controller().busy)return;stopLive();const input=kind==='camera'?$('dvV16CameraFile'):$('dvV16GalleryFile');try{root.DV_SCAN_V16_NATIVE_CAMERA.open(input,kind)}catch(error){controller().transition('error',{error})}}
  async function open(){fillFolders();void refreshBudget();try{$('dvV16Tcg').value=typeof selectedScanTcg!=='undefined'&&selectedScanTcg==='one_piece'?'one_piece':root.selectedScanTcg==='one_piece'?'one_piece':'pokemon'}catch{};if(!$('dvV16Dialog').open)$('dvV16Dialog').showModal();setMode(mode);controller().recover('Scanner bereit · Live-Kamera starten oder Foto wählen.');if(root.DV_SCAN_V16_STANDALONE)await startLive()}
  async function refreshBudget(){try{const budget=await root.DV_SCAN_V16_PROVIDER.budget(dbNow());$('dvV16EngineField').classList.toggle('dvV16Hidden',!budget.active);$('dvV16Budget').textContent=`Diese Woche: ${budget.remaining} Karten · ${budget.slabRemaining||0} Slabs übrig. Reset Montag 00:00 (Berlin).`;if(budget.active&&$('dvV16Engine').value==='local')$('dvV16Engine').value='openai';if(!budget.active){$('dvV16Engine').value='local';$('dvV16Kind').value='raw'}return budget}catch{$('dvV16EngineField').classList.add('dvV16Hidden');$('dvV16Engine').value='local';$('dvV16Kind').value='raw';return null}}
  async function analyzeWithProvider(source,options){
    let analysisSource=source;
    if(options.engine==='openai'&&!options.providerObservation&&!options.providerObservations){
      const kind=options.kind||'raw',isBatch=['multi','binder'].includes(options.mode);
      if(kind==='slab'&&isBatch)throw new Error('Grading-Slabs bitte einzeln oder als Serie scannen.');
      let regions=null,geometryInfo=null;
      if(options.mode==='binder'){
        const corrected=root.DV_SCAN_V16_GEOMETRY?.correctBinder?.(source)||{source,corrected:false,confidence:0};analysisSource=corrected.source;
        regions=root.DV_SCAN_V16_CORE.regionsFor(analysisSource,'binder','3x3');geometryInfo={binderPerspective:true,corrected:corrected.corrected,confidence:corrected.confidence};
      }else if(options.mode==='multi'&&options.layout==='auto'){
        regions=root.DV_SCAN_V16_GEOMETRY?.detectCardRects?.(source,{maxCards:12})||[];
        if(regions.length<2)throw new Error('Weniger als zwei Karten erkannt. Karten trennen oder ein festes Raster wählen.');
        geometryInfo={freeform:true,detected:regions.length};
      }else if(isBatch)regions=root.DV_SCAN_V16_CORE.regionsFor(source,options.mode,options.layout);
      const count=regions?.length||1,budget=await refreshBudget();
      const available=kind==='slab'?Number(budget?.slabRemaining||0):Number(budget?.remaining||0);if(!budget?.active||available<count)throw new Error(`Für diese Aufnahme werden ${count} ${kind==='slab'?'Slab-':'Karten-'}Scans benötigt. Verfügbar: ${available}.`);
      $('dvV16Status').textContent=`OpenAI analysiert ${count===1?'die Karte':count+' Kartenplätze'} …`;
      try{
        if(isBatch){const proposals=[];for(let i=0;i<regions.length;i++){options.onProgress?.({index:i,total:regions.length,phase:'recognize'});const crop=root.DV_SCAN_V16_CORE.canvasFrom(analysisSource,regions[i],1200);proposals.push(await root.DV_SCAN_V16_PROVIDER.recognize(crop,options.tcg,dbNow(),'raw'))}options={...options,providerObservations:proposals,providerReplay:false,regionsOverride:regions,geometryPrepared:true,geometryInfo}}
        else{const proposal=await root.DV_SCAN_V16_PROVIDER.recognize(source,options.tcg,dbNow(),kind);options={...options,[kind==='slab'?'slabObservation':'providerObservation']:proposal,providerReplay:false}}
      }finally{void refreshBudget()}
      if(options.slabObservation&&root.DV_V16_DEPS_READY)await root.DV_SCAN_V16_RUNTIME.withTimeout(root.DV_V16_DEPS_READY,30000,'Katalogprüfung für die Karte im Slab nicht verfügbar.');
    }
    return root.DV_SCAN_V16_CORE.analyze(analysisSource,options);
  }
  function close(){stopLive();$('dvV16Dialog').close()}
