    const subgrades=Array.isArray(v.subgrades)&&v.subgrades.length?`<small>Subgrades: ${esc(v.subgrades.map(x=>x.label+' '+x.value).join(' · '))}</small>`:'';
    return `<form class="dvV16Slab full" data-v16-slab="${index}"><strong>GRADING-LABEL ${row.slabConfirmed?'· BESTÄTIGT':''}</strong><p>Vorhandene Bewertung ablesen · keine neue KI-Benotung.</p><div class="dvV16Settings"><label>Firma<input name="company" value="${esc(v.company||'')}" maxlength="40" required></label><label>Grade<input name="grade" type="number" min="1" max="10" step="0.1" value="${esc(v.grade||'')}" required></label><label>Zertifikatsnummer · falls vorhanden<input name="certificateNumber" value="${esc(v.certificateNumber||'')}" maxlength="60"></label></div>${subgrades}<button class="btn secondary" type="submit">LABEL BESTÄTIGEN</button><small>Eine Zertifikatsnummer wird nicht beim Grading-Anbieter verifiziert. Kein Slab-Marktwert ermittelt.</small></form>`;
